// Lookup tables used by the decoders: mod data (data/mcsrranked.json, generated by datagen) plus
// vanilla 1.16.1 enums from data/mc_1_16_1.json.
import { LEGACY_TYPES, MOD_ENUMS, TIMELINE_TYPES } from './mod-data.ts';
import { MC_DATA } from './mc-data.ts';

export { MOD_VERSION, REPLAY_PUBLIC_KEY, WORLDS, TIMELINE_TYPES, LEGACY_TYPES, PIE_CHART_NAMES, FACTORY_READS } from './mod-data.ts';

export const ENUMS = {
  ...MOD_ENUMS,
  ...MC_DATA.enums,
  // InventorySlots.forEquipment(slot, 0) for each EquipmentSlot ordinal.
  EquipmentInventorySlot: [0, 40, 36, 37, 38, 39],
} as const;

export interface TypeDef {
  id: number;
  name: string;
  /** Decoder key in DECODERS. */
  factory: string;
  /** Canonical type the record is reported as. */
  storedAs: string;
}

export interface LegacyTypeDef extends TypeDef {
  /** Canonical TimeLineType name. */
  canonical: string;
}

export const TYPE_BY_ID: ReadonlyMap<number, TypeDef> = new Map(TIMELINE_TYPES.map((t): [number, TypeDef] =>
  [t.id, { id: t.id, name: t.name, factory: t.factory, storedAs: t.storedAs ?? t.name }]));
export const TYPE_BY_NAME: ReadonlyMap<string, TypeDef> = new Map([...TYPE_BY_ID.values()].map((t) => [t.name, t]));
export const LEGACY_BY_ID: ReadonlyMap<number, LegacyTypeDef> = new Map(LEGACY_TYPES.map((t): [number, LegacyTypeDef] => {
  const def = TYPE_BY_NAME.get(t.canonical);
  if (!def) throw new Error(`data/mcsrranked.json: legacy type ${t.name} maps to unknown type ${t.canonical}`);
  return [t.id, { id: t.id, name: t.name, canonical: t.canonical, factory: t.factory ?? def.factory, storedAs: def.storedAs }];
}));